defects.code:
FUNCTION @@proc@@ (p_text IN VARCHAR2) RETURN DATE IS
    l_d DATE;
BEGIN
    BEGIN
        BEGIN
            l_d := TO_DATE(SUBSTR(p_text, 1, 10)); -- @expect
        EXCEPTION
            WHEN VALUE_ERROR THEN
                l_d := NULL;
        END;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            l_d := NULL;
    END;
    RETURN l_d;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER, p_stamp IN VARCHAR2) IS
BEGIN
    IF p_stamp IS NULL THEN
        RETURN;
    END IF;
    INSERT INTO @@tab@@ (id, @@col@@)
    VALUES (p_id,
            TO_TIMESTAMP(p_stamp)); -- @expect
    @@proc2@@(p_id);
END @@proc@@;

FUNCTION @@proc@@ (p_code IN VARCHAR2) RETURN BOOLEAN IS
    l_limit NUMBER := @@num@@;
BEGIN
    IF p_code
       >= l_limit -- @expect
    THEN
        RETURN TRUE;
    END IF;
    RETURN FALSE;
END @@proc@@;

PROCEDURE @@proc@@ (p_when IN DATE, p_flag IN VARCHAR2) IS
BEGIN
    IF p_flag = 'Y' THEN
        NULL;
    ELSIF p_flag IS NULL THEN
        @@proc2@@(p_when);
    ELSE
        IF p_when /* cutoff */ > @@num@@ THEN -- @expect
            @@proc2@@(p_when + 1);
        END IF;
    END IF;
END @@proc@@;

PROCEDURE @@proc@@ (p_amount IN NUMBER) IS
    FUNCTION is_big (p_v IN NUMBER) RETURN BOOLEAN IS
    BEGIN
        IF p_v <> '@@str@@' THEN -- @expect
            RETURN TRUE;
        END IF;
        RETURN FALSE;
    END is_big;
BEGIN
    IF is_big(p_amount) THEN
        @@proc2@@(p_amount);
    END IF;
END @@proc@@;

negatives.code:
FUNCTION @@proc@@ (p_text IN VARCHAR2) RETURN DATE IS
    l_msg VARCHAR2(100);
    l_d   DATE;
BEGIN
    -- never call TO_DATE(p_text) without a mask
    l_msg := 'TO_DATE(p_text) is risky';
    l_d := TO_DATE(SUBSTR(p_text, 1, 10), 'YYYY-MM-DD');
    IF l_d IS NULL THEN
        l_d := TO_DATE('2000-01-01', 'YYYY-MM-DD', 'NLS_DATE_LANGUAGE=ENGLISH');
    END IF;
    @@proc2@@(l_msg);
    RETURN l_d;
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN NUMBER, p_s IN VARCHAR2) IS
    l_note VARCHAR2(100);
BEGIN
    -- p_n = 'abc' would be a bad comparison
    l_note := 'p_n = ''abc'' and p_s > 5';
    @@proc2@@(p_a => p_s, p_b => p_n);
    /* IF p_s = p_n THEN */
    IF p_n > 0 THEN
        @@proc2@@(p_a => l_note, p_b => 10);
    END IF;
END @@proc@@;

FUNCTION @@proc@@ (p_code IN VARCHAR2, p_n IN NUMBER, p_d IN DATE) RETURN BOOLEAN IS
    l_cnt  PLS_INTEGER := 0;
    l_text VARCHAR2(20) := 'abc';
    l_d    DATE := SYSDATE;
BEGIN
    IF p_code = l_text THEN
        RETURN TRUE;
    ELSIF p_n >= l_cnt AND p_code <> 'XYZ' THEN
        RETURN TRUE;
    ELSIF p_d < l_d THEN
        RETURN FALSE;
    END IF;
    RETURN FALSE;
END @@proc@@;

FUNCTION @@proc@@ (p_text IN VARCHAR2) RETURN DATE IS
    l_to_date DATE;
    l_to_timestamp_text VARCHAR2(30);
BEGIN
    l_to_timestamp_text := 'n/a';
    l_to_date := my_to_date(p_text);
    IF l_to_date IS NULL THEN
        l_to_date := Pkg_Dates.Parse_Date(p_text, l_to_timestamp_text);
    END IF;
    RETURN l_to_date;
END @@proc@@;

FUNCTION @@proc@@ (p_n IN NUMBER, p_s IN VARCHAR2) RETURN VARCHAR2 IS
    l_label VARCHAR2(30);
BEGIN
    IF p_s IS NOT NULL THEN
        l_label := CASE
                       WHEN p_n = 0 THEN 'zero'
                       WHEN p_n < 100 THEN 'small'
                       WHEN p_s = 'big' THEN 'text-big'
                       ELSE 'other'
                   END;
    END IF;
    RETURN l_label;
END @@proc@@;
